[CmdletBinding()]param([Parameter(Mandatory)][switch]$ApproveAndroidAccessibleEvidence,[Parameter(Mandatory)][ValidateSet('I_APPROVE_SECRETOBOOT_READ_ONLY_ANDROID_VOLUME_EVIDENCE')][string]$ConsentPhrase,[switch]$UseSyntheticWindowsPreflightForPreparation)
$ErrorActionPreference='Stop';Import-Module (Join-Path $PSScriptRoot 'SecretoBoot.WindowsLevel1.Manifest.psm1') -Force;Import-Module (Join-Path $PSScriptRoot 'SecretoBoot.AndroidAccessible.Manifest.psm1') -Force;$p=@{FeatureGateState=[bool]$ApproveAndroidAccessibleEvidence};if($UseSyntheticWindowsPreflightForPreparation){$p.UseSyntheticCapabilities=$true};$pre=& (Join-Path $PSScriptRoot 'Invoke-Preflight.ps1') @p;if(-not$pre.Ready){throw 'ANDROID_PREFLIGHT_DENIED'};$level1=New-SbLevel1ExecutionManifest -FeatureGateState $true -ExplicitConsent $true -PlatformCheck Passed;$manifest=New-SbAndroidAccessibleManifest -Level1ManifestDigest (Get-SbLevel1ManifestDigest $level1) -FeatureGateState $true -ExplicitConsent ($ConsentPhrase-eq'I_APPROVE_SECRETOBOOT_READ_ONLY_ANDROID_VOLUME_EVIDENCE') -NonElevated $pre.NonElevated -PlatformCheck Passed;$gate=Test-SbAndroidAccessibleManifest $manifest;if(-not$gate.Allowed){throw ('ANDROID_MANIFEST_DENIED: '+($gate.DiagnosticCodes-join','))};[pscustomobject][ordered]@{Manifest=$manifest;Digest=Get-SbAndroidAccessibleManifestDigest $manifest;InventoryOperationsExecuted=0;OrdinaryVolumeReads=0;EfiOperations=0;Writes=0;MountOperations=0}
